// storagePath.ts
// ============================================================================
// Cross-platform resolution of:
//   1. VS Code's live globalStorage/storage.json (the curator's INPUT).
//   2. The directory containing it (default OUTPUT location).
//
// Strategy: instead of guessing per-platform paths (which breaks for portable
// installs, custom --user-data-dir, Insiders vs Stable, OSS, etc.), we derive
// from the extension's own `globalStorageUri`. VS Code lays out:
//
//   <user-data-dir>/User/globalStorage/
//     storage.json                              <-- what we want
//     <publisher>.<extension>/                  <-- context.globalStorageUri
//
// So `context.globalStorageUri` is always exactly two levels deep under the
// globalStorage directory we need. This works on macOS, Linux, Windows,
// portable installs, codespaces, and remote sessions alike.
// ============================================================================

import * as path from "path";
import * as os from "os";
import * as vscode from "vscode";

export interface ResolvedPaths {
    /** Absolute path to VS Code's globalStorage directory. */
    globalStorageDir: string;
    /** Absolute path to the live storage.json. */
    liveStorageJson: string;
    /** Absolute path of the curated output (after applying user setting). */
    curatedOutput: string;
}

export function resolvePaths(
    context: vscode.ExtensionContext,
    userOverride: string,
): ResolvedPaths {
    // context.globalStorageUri = <globalStorage>/<publisher>.<ext>
    // -> parent is <globalStorage>.
    const extStorage = context.globalStorageUri.fsPath;
    const globalStorageDir = path.dirname(extStorage);
    const liveStorageJson = path.join(globalStorageDir, "storage.json");

    let curatedOutput: string;
    const trimmed = (userOverride ?? "").trim();
    if (trimmed === "") {
        curatedOutput = path.join(globalStorageDir, "storage.curated.json");
    } else {
        curatedOutput = expand(trimmed);
        if (!path.isAbsolute(curatedOutput)) {
            // Resolve relative paths against the globalStorage dir for
            // determinism (CWD is not meaningful in an extension host).
            curatedOutput = path.resolve(globalStorageDir, curatedOutput);
        }
    }

    return { globalStorageDir, liveStorageJson, curatedOutput };
}

function expand(p: string): string {
    let out = p;
    // Leading ~ -> home directory.
    if (out === "~" || out.startsWith("~/") || out.startsWith("~\\")) {
        out = path.join(os.homedir(), out.slice(1));
    }
    // ${userHome} and ${env:NAME}
    out = out.replace(/\$\{userHome\}/g, os.homedir());
    out = out.replace(/\$\{env:([^}]+)\}/g, (_, name) => process.env[name] ?? "");
    return out;
}
